-- Phase 3a: people, businesses, who belongs to which business, and an append-only audit log.
-- Ids are generated by the application. Timestamps come from the application's injected Clock.

CREATE TABLE users (
    id               uuid PRIMARY KEY,
    -- The identity provider's stable user id (the JWT "sub"); Cognito or the local mock server.
    identity_subject varchar(255) NOT NULL UNIQUE,
    email            varchar(320) NOT NULL,
    phone            varchar(20),
    display_name     varchar(100),
    preferred_locale varchar(2)   NOT NULL DEFAULT 'en',
    status           varchar(20)  NOT NULL DEFAULT 'ACTIVE',
    created_at       timestamptz  NOT NULL,
    updated_at       timestamptz  NOT NULL,
    CONSTRAINT users_email_lowercase CHECK (email = lower(email)),
    CONSTRAINT users_preferred_locale_check CHECK (preferred_locale IN ('en', 'te', 'hi')),
    CONSTRAINT users_status_check CHECK (status IN ('ACTIVE', 'SUSPENDED'))
);

CREATE UNIQUE INDEX users_email_key ON users (email);

CREATE TABLE businesses (
    id                  uuid PRIMARY KEY,
    legal_name          varchar(200) NOT NULL,
    trade_name          varchar(200),
    business_type       varchar(20)  NOT NULL,
    gstin               varchar(15) UNIQUE,
    city                varchar(100) NOT NULL,
    state               varchar(100) NOT NULL,
    pincode             varchar(6)   NOT NULL,
    verification_status varchar(20)  NOT NULL DEFAULT 'UNVERIFIED',
    created_at          timestamptz  NOT NULL,
    updated_at          timestamptz  NOT NULL,
    CONSTRAINT businesses_type_check CHECK (business_type IN
        ('KIRANA', 'WHOLESALER', 'DISTRIBUTOR', 'MANUFACTURER', 'RETAILER', 'OTHER')),
    CONSTRAINT businesses_gstin_format CHECK (gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
    CONSTRAINT businesses_pincode_format CHECK (pincode ~ '^[1-9][0-9]{5}$'),
    CONSTRAINT businesses_verification_status_check CHECK (verification_status IN
        ('UNVERIFIED', 'PENDING', 'VERIFIED', 'REJECTED'))
);

CREATE TABLE business_memberships (
    id          uuid PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES users (id),
    business_id uuid        NOT NULL REFERENCES businesses (id),
    role        varchar(20) NOT NULL,
    created_at  timestamptz NOT NULL,
    CONSTRAINT business_memberships_user_business_key UNIQUE (user_id, business_id),
    CONSTRAINT business_memberships_role_check CHECK (role IN ('OWNER', 'MANAGER', 'STAFF'))
);

CREATE INDEX business_memberships_business_id_idx ON business_memberships (business_id);

-- No foreign keys: audit rows must outlive anything they mention.
CREATE TABLE audit_events (
    id             uuid PRIMARY KEY,
    occurred_at    timestamptz  NOT NULL,
    actor_user_id  uuid,
    business_id    uuid,
    action         varchar(100) NOT NULL,
    target_type    varchar(50)  NOT NULL,
    target_id      uuid,
    request_id     varchar(64),
    details        jsonb        NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX audit_events_business_id_occurred_at_idx ON audit_events (business_id, occurred_at);

-- Append-only: the database itself refuses to change or remove audit history.
CREATE FUNCTION audit_events_reject_change() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION 'audit_events is append-only (% rejected)', TG_OP;
END;
$$;

CREATE TRIGGER audit_events_no_update_or_delete
    BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION audit_events_reject_change();

CREATE TRIGGER audit_events_no_truncate
    BEFORE TRUNCATE ON audit_events
    FOR EACH STATEMENT EXECUTE FUNCTION audit_events_reject_change();
